import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename
    try:
        response = requests.get(url, stream=True, timeout=10)
        response.raise_for_status()
        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        return (f"Error downloading file: {e}", [])
    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)
    except (zipfile.BadZipFile, OSError) as e:
        return (f"Error extracting zip file: {e}", [])
    filenames = []
    for path in ZIP_DIR.rglob("*"):
        if path.is_file():
            filenames.append(str(path.relative_to(ZIP_DIR)))
    return ("Download and extraction successful", filenames)

import os
import requests
from zipfile import ZipFile, BadZipFile
def task_func(url, download_path="mnt/data/downloads/"):
    try:
        if not isinstance(url, str) or not url.strip():
            return "Error: Unable to download the file from the provided URL."
        os.makedirs(download_path, exist_ok=True)
        try:
            response = requests.get(url, stream=True, timeout=30)
            response.raise_for_status()
        except requests.RequestException:
            return "Error: Unable to download the file from the provided URL."
        content_type = response.headers.get("Content-Type", "").split(";")[0].strip().lower()
        if content_type != "application/zip":
            return "Error: The URL does not point to a ZIP file."
        filename = os.path.basename(url) or "downloaded.zip"
        if not filename.lower().endswith(".zip"):
            filename += ".zip"
        zip_path = os.path.join(download_path, filename)
        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
        extract_dir_name = os.path.splitext(filename)[0]
        extract_dir = os.path.join(download_path, extract_dir_name)
        os.makedirs(extract_dir, exist_ok=True)
        try:
            with ZipFile(zip_path, "r") as zip_ref:
                zip_ref.extractall(extract_dir)
        except BadZipFile:
            return "Error: The downloaded file is not a valid ZIP file."
        return extract_dir
    except Exception as e:
        return f"Error: {e}"

