        raise ValueError("JSON response does not contain 'data' key.")
    data_field = payload["data"]
    if isinstance(data_field, (list, tuple)):
        text = " ".join(str(item) for item in data_field)
    else:
        text = str(data_field)
    matches = regex.findall(text)
    csv_filename = "matched_data.csv"
    abs_path = os.path.abspath(csv_filename)
    with open(csv_filename, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["match"])
        for m in matches:
            if isinstance(m, tuple):
                writer.writerow(["".join(m)])
            else:
                writer.writerow([m])
    return abs_path

