import zipfile
def task_func(url, destination_directory, headers=None):
    if not isinstance(url, str) or not url:
        raise ValueError("URL must be a non-empty string")
    if not isinstance(destination_directory, str) or not destination_directory:
        raise ValueError("Destination directory must be a non-empty string")
    if headers is None:
        headers = {}
    os.makedirs(destination_directory, exist_ok=True)
    zip_path = os.path.join(destination_directory, "downloaded.zip")
    try:
        response = requests.get(url, headers=headers, stream=True, timeout=30)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip file: {e}")
    with open(zip_path, "wb") as f:
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                f.write(chunk)
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(destination_directory)
            for info in zf.infolist():
                if not info.is_dir():
                    extracted_files.append(info.filename)
    except zipfile.BadZipFile as e:
        raise ValueError(f"Downloaded file is not a valid zip archive: {e}")
    return extracted_files

